{"code":"def transform(grid):
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        n=len(row)
        # smallest repeating horizontal period compatible with every visible cell
        pfound=None
        for p in range(1,n+1):
            ok=True
            vals={}
            for c,v in enumerate(row):
                if v!=0:
                    k=c%p
                    if k in vals and vals[k]!=v:
                        ok=False; break
                    vals[k]=v
            if ok:
                pfound=p; break
        p=pfound or n
        vals={}
        for c,v in enumerate(row):
            if v!=0: vals[c%p]=v
        # normally every residue is observed; for any absent residue use nearest
        for c,v in enumerate(row):
            if v==0:
                if c%p in vals: out[r][c]=vals[c%p]
                else:
                    # infer from neighboring residues in the visible cycle
                    for d in range(1,p+1):
                        if (c-d)%p in vals: out[r][c]=vals[(c-d)%p]; break

    return out"}

